    {!load.emptyUld&&<b className="load-plan-card-commodity" aria-label={`${load.commodity??(load.specialLoadCodes.includes("BAG")?"BAGGAGE":"CARGO")} load`}>{cardCommodityCode(load)}</b>}
    {!isBulk&&!load.emptyUld&&<span className="load-plan-card-route">{unloadStation(load)} · {cardCommodityCode(load)}</span>}
